import os
import google.cloud.documentai_v1 as documentai

def extract_receipt_fields(payload, config=None):
    config = config or {}
    project_id = os.environ.get("GOOGLE_CLOUD_PROJECT")
    location = "us"  # Or your preferred region, e.g., "eu"
    processor_id = config.get("processor_id", "a4a3767223f03b57")  # Pre-trained Receipt Parser ID

    if not project_id:
        raise ValueError("GOOGLE_CLOUD_PROJECT environment variable must be set.")

    documentai_client = documentai.DocumentProcessorServiceClient()

    processor_name = documentai_client.processor_path(project_id, location, processor_id)

    # The payload is assumed to be a byte string (e.g., image data)
    raw_document = documentai.RawDocument(content=payload, mime_type="application/pdf") # Or "image/jpeg", "image/png"

    request = documentai.ProcessRequest(name=processor_name, raw_document=raw_document)

    response = documentai_client.process_document(request=request)

    document = response.document

    # Initialize fields
    merchant_name = None
    tax_amount = None
    total_amount = None
    items = []

    # Extract fields from entities
    for entity in document.entities:
        if entity.type == "merchant_name":
            merchant_name = entity.text_anchor.content if entity.text_anchor.content else entity.mention_text
        elif entity.type == "total_amount":
            total_amount = entity.text_anchor.content if entity.text_anchor.content else entity.mention_text
        elif entity.type == "tax_amount":
            tax_amount = entity.text_anchor.content if entity.text_anchor.content else entity.mention_text
        elif entity.type == "line_item":
            item = {}
            for prop in entity.properties:
                if prop.type == "description":
                    item["description"] = prop.text_anchor.content if prop.text_anchor.content else prop.mention_text
                elif prop.type == "price":
                    item["price"] = prop.text_anchor.content if prop.text_anchor.content else prop.mention_text
                elif prop.type == "quantity":
                    item["quantity"] = prop.text_anchor.content if prop.text_anchor.content else prop.mention_text
            if item:
                items.append(item)

    result = {
        "merchant": merchant_name,
        "tax": tax_amount,
        "total": total_amount,
        "items": items,
    }
    return result
